with open('F:/Dev/projects/CapRust/android/app/src/main/java/domica/caprust/editor/EditorActivity.kt', 'r', encoding='utf-8') as f:
    content = f.read()
old = "                val label = clip.optString(\"name\", clip.optString(\"path\", \"?\"))\n                timeline.addView(\n                    TextView(this).apply {\n                        setText(label)\n                        setTextColor(0xFFE8EAED.toInt())\n                        textSize = 14f\n                        setPadding(0, dp(6), 0, dp(6))\n                    },\n                )"
new = "                val label = clip.optString(\"name\").ifEmpty { clip.optString(\"path\", \"?\") }\n                val nameText = if (label.isNotEmpty()) label else \"Clip $i\"\n                val dur = clip.optLong(\"duration_ms\", 5000)\n                val track = clip.optInt(\"track_index\", 0)\n                val labelStr = \"$nameText (${dur / 1000}s, T$track)\"\n                val tv = TextView(this).apply {\n                    setText(labelStr)\n                    setTextColor(0xFFE8EAED.toInt())\n                    textSize = 13f\n                    setPadding(dp(8), dp(4), dp(8), dp(4))\n                    setBackgroundColor(0xFF252530.toInt())\n                }\n                tv.setOnTouchListener { v, event ->\n                    when (event.action) {\n                        android.view.MotionEvent.ACTION_DOWN -> {\n                            v.tag = event.rawX.toInt()\n                            true\n                        }\n                        android.view.MotionEvent.ACTION_MOVE -> {\n                            val prev = v.tag as? Int ?: event.rawX.toInt()\n                            val dx = event.rawX.toInt() - prev\n                            v.tag = event.rawX.toInt()\n                            v.x += dx\n                            true\n                        }\n                        else -> false\n                    }\n                }\n                timeline.addView(tv)"
content = content.replace(old, new)
with open('F:/Dev/projects/CapRust/android/app/src/main/java/domica/caprust/editor/EditorActivity.kt', 'w', encoding='utf-8') as f:
    f.write(content)
print("done")
